;// CONCATENATED MODULE: ./src/reporters/actionReporter.ts


async function actionReporter(headline, reports, summary) {
    const byRule = groupBy(reports, (report) => report.about.name);
    summary.addHeading("OctoGuide Report", 1);
    summary.addRaw((await x.parse(headline)) + "\n\n");
    for (const ruleReports of Object.values(byRule)) {
        const { about } = ruleReports[0];
        summary.addHeading(`<a href="${about.url}">${about.name}</a>`, 2);
        summary.addRaw(await x.parse(about.explanation.join(" ")));
        for (const report of ruleReports) {
            summary.addRaw(await x.parse(report.data.primary));
            if (report.data.secondary) {
                summary.addRaw(await x.parse(report.data.secondary.join(" ")));
            }
            summary.addRaw(await x.parse(report.data.suggestion.join("\n")));
        }
    }
    summary.addSeparator();
    summary.addRaw(`🗺️ <em>This message was posted automatically by <a href="https://github.com/OctoGuide/bot">OctoGuide</a>: a bot for GitHub repository best practices.</em>`);
}

;// CONCATENATED MODULE: ./src/reporters/createHeadlineAsMarkdown.ts
const listFormat = new Intl.ListFormat("en", { type: "conjunction" });
function createHeadlineAsMarkdown(entity, reports, logins = entity.data.user ? [entity.data.user.login] : []) {
    const entityAlias = entity.type.replace("_", " ");
    const entityText = entity.type === "comment"
        ? `[${entityAlias}](${entity.data.html_url} "comment ${entity.data.id.toString()} reported by OctoGuide")`
        : entityAlias;
    return [
        "👋 Hi",
        logins.length
            ? ` ${listFormat.format(logins.map((login) => `@${login}`))}`
            : "",
        ", thanks for the ",
        entityText,
        "! A scan flagged ",
        reports.length > 1 ? "some concerns" : "a concern",
        " with it. Could you please take a look?",
    ].join("");
}

